const SUPPORTED_FORMATS = ["image/jpg", "image/jpeg", "image/png"];
const validationSchema = yup.object().shape({
  images: yup
    .mixed()
    .required("image is required")
    .test(
      "fileFormat",
      "Unsupported Format. Only jpg, png, jpeg are allowed.",
      (value) => value && SUPPORTED_FORMATS.includes(value.type)
    ),
});

const FileInput = ({ inputId, accept, onChange, selectedFileName, error }) => (
  <>
    <Button
      startIcon={<UploadIcon />}
      variant="contained"
      sx={{ bgcolor: "#fff", border: "1px solid #6B6B6B", color: "#000" }}
      onClick={() => document.getElementById(inputId).click()}
    >
      Choose File
    </Button>
    <input
      id={inputId}
      name={inputId}
      type="file"
      accept={accept}
      onChange={onChange}
      style={{ display: "none" }}
    />
    <FormHelperText
      variant="body2"
      sx={{ color: "#6B6B6B", marginBottom: "8px" }}
    >
      {selectedFileName || "No file chosen"}
    </FormHelperText>
    <FormHelperText
      variant="body2"
      sx={{ color: "error.main", marginBottom: "8px" }}
    >
      {error && error.message}
    </FormHelperText>
  </>
);

